import { TransformNode, SceneLoader } from '@babylonjs/core';
import { applyModelPaint } from '../../../utils/modelPaint.js';

// Light hull — M24 Chaffee-inspired, generated by scripts/modelgen/light_hull_scout.py.

const PAINT = { paintColor: [0.78, 0.12, 0.08] };

export default {
  id: 'light-hull-scout',
  name: 'Light Hull',
  category: 'hull',
  stats: {},
  mountEmpty: 'turret',
  nativeTurret: 'light-turret-enclosed',
  ringDiameter: 1.6,   // mirrors ringD in scripts/modelgen/params/
  footprint: { halfW: 1.35, halfD: 2.1 },   // collision box (authored, not measured) — light/short

  async build(scene, paintOverride = null) {
    const result = await SceneLoader.ImportMeshAsync('', '/assets/models/tanks/parts/', 'light_hull_scout.glb', scene);
    const mountNode = result.transformNodes.find(n => n.name === this.mountEmpty);
    const mount = mountNode ? mountNode.getAbsolutePosition().clone() : null;

    const root = new TransformNode('hull_light_scout_root', scene);
    const meshes = result.meshes.filter(m => m.name !== '__root__');
    for (const m of meshes) m.setParent(root);

    applyModelPaint(meshes, PAINT, scene, paintOverride);
    return { root, meshes, mount, ringCenter: mount };
  },
};
